(6108356, 899607, 56545, '<td valign="top">The chain doesn''t look as sharp as it could be, but I like the lighting and composition.</td>', 'The chain doesn''t look as sharp as it could be, but I like the lighting and composition.', '2010-07-29 08:50:23.000000', NULL, 1),
(6108357, 899331, 56545, '<td valign="top">It''s too bad there''s so much noise here; I would guess either too high an ISO, too low a resolution, over-processed or taken with a camera phone... with a little more detail, the shapes in this image would be quite good.</td>', 'It''s too bad there''s so much noise here; I would guess either too high an ISO, too low a resolution, over-processed or taken with a camera phone... with a little more detail, the shapes in this image would be quite good.', '2010-07-29 08:53:18.000000', NULL, 1),
(6108360, 900124, 56545, '<td valign="top">not really a big fan of inverted or negative images, though perhaps it is more interesting this way than the original...</td>', 'not really a big fan of inverted or negative images, though perhaps it is more interesting this way than the original...', '2010-07-29 09:02:38.000000', NULL, 1),
(6108361, 899592, 56545, '<td valign="top">I really like the mood of this one - the title says it all.</td>', 'I really like the mood of this one - the title says it all.', '2010-07-29 09:03:52.000000', NULL, 1),
