(6108573, 899127, 117314, '<td valign="top">Nice shot with good colour processing. Background seems a little distracting. But thats quite ok I guess. 9</td>', 'Nice shot with good colour processing. Background seems a little distracting. But thats quite ok I guess. 9', '2010-07-29 14:13:23.000000', NULL, 1),
