INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6109974, 899775, 66597, '<td valign="top">I like the sunburst a lot but not sure about the angle - looks a little cut-off on the left.</td>', 'I like the sunburst a lot but not sure about the angle - looks a little cut-off on the left.', '2010-07-30 23:17:31.000000', NULL, 1),
(6109976, 900069, 66597, '<td valign="top">This would be great with a star filter. It''s nicely exposed, at any rate.</td>', 'This would be great with a star filter. It''s nicely exposed, at any rate.', '2010-07-30 23:19:05.000000', NULL, 1),
(6109977, 899739, 66597, '<td valign="top">I like the mood here.</td>', 'I like the mood here.', '2010-07-30 23:19:34.000000', NULL, 1),
(6109978, 899414, 66597, '<td valign="top">This is scary - I''m imagining an electric chair or something behind that door... very good use of emotive.</td>', 'This is scary - I''m imagining an electric chair or something behind that door... very good use of emotive.', '2010-07-30 23:20:22.000000', NULL, 1),
(6109979, 899038, 66597, '<td valign="top">You''ll probably get slammed by the voters, but I really like this. Although it does remind me of a concentration camp. 8</td>', 'You''ll probably get slammed by the voters, but I really like this. Although it does remind me of a concentration camp. 8', '2010-07-30 23:21:24.000000', NULL, 1),
(6109985, 899072, 66597, '<td valign="top">I like a lot about this photo but think it would be a lot more enticing with greater definition between blacks and whites (looks a bit gray).</td>', 'I like a lot about this photo but think it would be a lot more enticing with greater definition between blacks and whites (looks a bit gray).', '2010-07-30 23:25:14.000000', NULL, 1),
(6109986, 900054, 66597, '<td valign="top">Not a bad shot but seems like a shoehorn for the challenge...</td>', 'Not a bad shot but seems like a shoehorn for the challenge...', '2010-07-30 23:25:33.000000', NULL, 1),
(6109990, 899621, 46918, '<td valign="top">The lighting is kindof blah....I would have liked more definition with the clouds.</td>', 'The lighting is kindof blah....I would have liked more definition with the clouds.', '2010-07-30 23:37:37.000000', NULL, 1),
(6109992, 899414, 46918, '<td valign="top">I love the detail in the walls</td>', 'I love the detail in the walls', '2010-07-30 23:38:06.000000', NULL, 1),
(6110004, 899592, 96751, '<td valign="top">Beautiful mood.  Great use of twilight lighting.</td>', 'Beautiful mood.  Great use of twilight lighting.', '2010-07-31 00:02:44.000000', NULL, 1),
(6110005, 900156, 96751, '<td valign="top">Powerful lines and strong colors.  Perhaps just a bit oversaturated.</td>', 'Powerful lines and strong colors.  Perhaps just a bit oversaturated.', '2010-07-31 00:03:27.000000', NULL, 1),
(6110006, 899027, 96751, '<td valign="top">I love the delicate quality of this image, the clean lines and tonal qualities make this abstract very compelling.</td>', 'I love the delicate quality of this image, the clean lines and tonal qualities make this abstract very compelling.', '2010-07-31 00:04:06.000000', NULL, 1),
(6110007, 900071, 96751, '<td valign="top">Wonderful lines.</td>', 'Wonderful lines.', '2010-07-31 00:05:21.000000', NULL, 1),
(6110008, 900179, 96751, '<td valign="top">For me, this is an example of where the processing is more interesting than the content of the image, and makes an otherwise average shot more interesting.</td>', 'For me, this is an example of where the processing is more interesting than the content of the image, and makes an otherwise average shot more interesting.', '2010-07-31 00:06:29.000000', NULL, 1),
(6110038, 900030, 96751, '<td valign="top">The wall is very interesting, and perhaps a different, lower angle pointing up at it might have made a more dynamic shot.</td>', 'The wall is very interesting, and perhaps a different, lower angle pointing up at it might have made a more dynamic shot.', '2010-07-31 00:19:38.000000', NULL, 1),
(6110041, 899172, 96751, '<td valign="top">I just love the reflection of the sky in the dishes.  Beautiful.</td>', 'I just love the reflection of the sky in the dishes.  Beautiful.', '2010-07-31 00:22:46.000000', NULL, 1),
(6110048, 898822, 96751, '<td valign="top">Gorgeous.  Not sure it''s very "industrial", but the quality of the image is sensational.  Great reflection, tones, composition.</td>', 'Gorgeous.  Not sure it''s very "industrial", but the quality of the image is sensational.  Great reflection, tones, composition.', '2010-07-31 00:26:09.000000', NULL, 1),
(6110076, 900054, 96751, '<td valign="top">Great macro.  OOB thinking!</td>', 'Great macro.  OOB thinking!', '2010-07-31 00:42:00.000000', NULL, 1),
(6110080, 900144, 96751, '<td valign="top">Interesting abstract.  Would have like it more if I could see how the two elements relate to each other.</td>', 'Interesting abstract.  Would have like it more if I could see how the two elements relate to each other.', '2010-07-31 00:43:02.000000', NULL, 1),
(6110082, 900136, 96751, '<td valign="top">Nice, gritty image, but just a tad dark.</td>', 'Nice, gritty image, but just a tad dark.', '2010-07-31 00:44:16.000000', NULL, 1),
(6110085, 899621, 96751, '<td valign="top">Nice.  I like the symmetry and the moody sky.</td>', 'Nice.  I like the symmetry and the moody sky.', '2010-07-31 00:46:06.000000', NULL, 1),
(6110086, 899433, 96751, '<td valign="top">Strong lines.  Interest added with the tilt.  Good choice in b/w.</td>', 'Strong lines.  Interest added with the tilt.  Good choice in b/w.', '2010-07-31 00:46:53.000000', NULL, 1),
(6110088, 900171, 96751, '<td valign="top">Wonderful contrast.  Very Bladerunner.</td>', 'Wonderful contrast.  Very Bladerunner.', '2010-07-31 00:47:51.000000', NULL, 1),
(6110089, 900001, 96751, '<td valign="top">Very interesting instrument.</td>', 'Very interesting instrument.', '2010-07-31 00:48:17.000000', NULL, 1),
(6110137, 899083, 46918, '<td valign="top">Looks about like the gulf coast...allot of fishing boats down here are at the docks.</td>', 'Looks about like the gulf coast...allot of fishing boats down here are at the docks.', '2010-07-31 01:25:22.000000', NULL, 1),
(6110174, 898714, 96751, '<td valign="top">Very interesting image.  It looks like an illustration.  I look forward to learning where/what this is.</td>', 'Very interesting image.  It looks like an illustration.  I look forward to learning where/what this is.', '2010-07-31 01:43:47.000000', NULL, 1),
(6110181, 900196, 96751, '<td valign="top">This could have worked in the Minimalism challenge as well!  Very nice.  Great tones and dof.</td>', 'This could have worked in the Minimalism challenge as well!  Very nice.  Great tones and dof.', '2010-07-31 01:54:06.000000', NULL, 1),
(6110183, 900178, 96751, '<td valign="top">Fabulous.  I LOVE this image.  It is both very complex and very simple.  It has multiple layers, and diverging lines.  It is varied in tones, solid and diaphanous.  It is marvelous.  A dream and a nightmare, and a peak into someone else''s life.</td>', 'Fabulous.  I LOVE this image.  It is both very complex and very simple.  It has multiple layers, and diverging lines.  It is varied in tones, solid and diaphanous.  It is marvelous.  A dream and a nightmare, and a peak into someone else''s life.', '2010-07-31 01:56:21.000000', NULL, 1),
(6110245, 899592, 86218, '<td valign="top">Lovely shot and like the dark mood that fits the desolate theme to this. You have the old and then the new in distant background. Slow shutter compliments the mood with glass water and worn wood structures. Like it. Was 7 - now 8</td>', 'Lovely shot and like the dark mood that fits the desolate theme to this. You have the old and then the new in distant background. Slow shutter compliments the mood with glass water and worn wood structures. Like it. Was 7 - now 8', '2010-07-31 06:34:28.000000', NULL, 1),
(6110246, 899696, 86218, '<td valign="top">Clynical shot of this factory. Like the star burst in the lights. Looks a bit empty/quiet and would like to have seen some activity with this by way of truck or moving figures. Yes it''s after hours...but then this is industry and you have chosen a close frame on this that should also tell a story. is that a Figure on the stairs? If so the idea is there but more movement and figures would bring accross the idea stronger. Im nit picking..but then I only do that on pics I like</td>', 'Clynical shot of this factory. Like the star burst in the lights. Looks a bit empty/quiet and would like to have seen some activity with this by way of truck or moving figures. Yes it''s after hours...but then this is industry and you have chosen a close frame on this that should also tell a story. is that a Figure on the stairs? If so the idea is there but more movement and figures would bring accross the idea stronger. Im nit picking..but then I only do that on pics I like', '2010-07-31 06:40:21.000000', NULL, 1),
(6110247, 900011, 86218, '<td valign="top">Plain simple yet effective. Nice comp to this</td>', 'Plain simple yet effective. Nice comp to this', '2010-07-31 06:40:54.000000', NULL, 1),
(6110248, 900122, 86218, '<td valign="top">Top contender in my books. I think you made the right choice in doing this B&amp;W. Really really like this. 9</td>', 'Top contender in my books. I think you made the right choice in doing this B&W. Really really like this. 9', '2010-07-31 06:42:17.000000', NULL, 1),
(6110249, 899663, 86218, '<td valign="top">Very nice shot and fits the theme. got some unwanted ghost effects in this and a bit of bother but still a nice industrial shot. Like the tracks in the foreground and this could maybe have been used with greater effect in the compo to lead the eyes to the scene, - lower angle closer to the tracks etc. Just a thought. Nice wotk with star bursts in the lights.</td>', 'Very nice shot and fits the theme. got some unwanted ghost effects in this and a bit of bother but still a nice industrial shot. Like the tracks in the foreground and this could maybe have been used with greater effect in the compo to lead the eyes to the scene, - lower angle closer to the tracks etc. Just a thought. Nice wotk with star bursts in the lights.', '2010-07-31 06:45:55.000000', NULL, 1),
